//go:build goexperiment.simd

package test_helpers

import (
	"testing"
)

func ReduceSum[S number](s []S) S {
	var x S
	for _, v := range s {
		x += v
	}
	return x
}

type Vec[E number] interface {
	Store(s []E)
	Len() int
}

// TestV2S tests the simd unary method f against the expected behavior generated by want
func TestV2S[S number, V Vec[S]](t *testing.T, slice []S, load func([]S) V, f func(_ V) S, want func(_ []S) S) {
	var v V
	n := v.Len()
	t.Helper()
	forSlice(t, slice, n, func(x []S) bool {
		t.Helper()
		a := load(x)
		g := f(a)
		w := want(x)
		return CheckScalarsLogInput(t, g, w, 0.000001, func() { t.Helper(); t.Logf("x=%v", x) })
	})
}
